          title: "<div id='" + (ele.id + num) + "' data-uk-tooltip='pos: right; animation: true; offset: 12;' title=\"" + text + '">' + mati + " " + ele.name + "<input onclick='corregida(" + ele.id + ",this.checked" + ")' style='position: absolute; right: 15px;' type='checkbox' " + (ele.corregida ? "checked" : "") + "></div>",
          startDate: Date.UTC(fechas[0], fechas[1] - 1, fechas[2]),
